    property: 'whether the aerobic supply can pay the drag power of holding station in a current',
    relation: 'ρ_w C_d A U_current^3 / 2 ≤ η E_O2 Q Ca', symbols: { ρ_w: 'water_density_kg_m3', C_d: 'drag_coefficient', A: 'drag_area_m2', U_current: 'current_speed_m_s', 'η E_O2 Q Ca': 'aerobic_ceiling_W' },
    requires: ['water_density_kg_m3', 'drag_coefficient', 'drag_area_m2', 'current_speed_m_s', 'aerobic_ceiling_W'], appliesWhen: ['station_holding_drag_fick', 'fick_aerobic_supply'],
